import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));

        String line = f.readLine();
        int[] a = new int[6];
        for (int i = 0; i < 6; i++) {
            a[i] = Character.getNumericValue(line.charAt(i));
        }

        int sum1 = a[0] + a[1] + a[2];
        int sum2 = a[3] + a[4] + a[5];

        if (sum1 == sum2) {
            System.out.println(0);
        } else {
            int[] a1 = new int[]{a[0], a[1], a[2]};
            int[] a2 = new int[]{a[3], a[4], a[5]};
            Arrays.sort(a1);
            Arrays.sort(a2);

            int[] changes = new int[6];
            if (sum1 > sum2) {
                for (int k = 0; k < 3; k++) {
                    changes[k] = a1[k];
                    changes[k + 3] = 9 - a2[k];
                }
            } else {
                for (int k = 0; k < 3; k++) {
                    changes[k] = a2[k];
                    changes[k + 3] = 9 - a1[k];
                }
            }

            Arrays.sort(changes);

            int dif = Math.abs(sum1 - sum2);

            int sumdif = 0;
            int answer = 0;
            int i = 5;
            while (sumdif < dif) {
                sumdif += changes[i];
                i--;
                answer++;
            }

            System.out.println(answer);
        }
    }
}

